import{_ as e,o as r,c as t,a5 as i}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"C# 知识库","description":"这套内容面向已经掌握任意一门编程语言、希望系统学习 C# 与 .NET 并具备独立开发能力的开发者。读完全部核心路径后，你能用 C# 写出结构清晰的程序，理解 .NET 的编译模型、运行时与核心库，并把它们用于 Web、数据访问与并发场景。","frontmatter":{},"headers":[],"relativePath":"csharp/index.md","filePath":"csharp/index.md"}'),s={name:"csharp/index.md"};function d(c,a,l,n,h,o){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="c-知识库" tabindex="-1" data-src-line="1" data-src-file="csharp/index.md">C# 知识库 <a class="header-anchor" href="#c-知识库" aria-label="Permalink to &quot;C# 知识库&quot;">​</a></h1><p data-src-line="3" data-src-file="csharp/index.md">这套内容面向已经掌握任意一门编程语言、希望系统学习 C# 与 .NET 并具备独立开发能力的开发者。读完全部核心路径后，你能用 C# 写出结构清晰的程序，理解 .NET 的编译模型、运行时与核心库，并把它们用于 Web、数据访问与并发场景。</p><blockquote data-src-line="5" data-src-file="csharp/index.md"><p data-src-line="5" data-src-file="csharp/index.md">本专题以 <strong>.NET 10 LTS + C# 14</strong> 为基线，该版本支持至 2028-11-14。涉及版本差异的结论都会标明适用版本；版本支持状态见 <a href="https://dotnet.microsoft.com/platform/support/policy" target="_blank" rel="noreferrer">.NET 官方支持策略</a>。</p></blockquote><h2 id="内容地图" tabindex="-1" data-src-line="7" data-src-file="csharp/index.md">内容地图 <a class="header-anchor" href="#内容地图" aria-label="Permalink to &quot;内容地图&quot;">​</a></h2><ul data-src-line="9" data-src-file="csharp/index.md"><li data-src-line="9" data-src-file="csharp/index.md"><strong><a href="./01-csharp-language/chapter-01-why-csharp.html">01 C# 语言</a></strong>：认识 .NET 与 C#、类型系统、对象与值语义、面向对象、泛型、特性、委托与 Lambda、异常、集合与 LINQ、序列化、反射、表达式树，以及 record、模式匹配与可空引用类型等现代特性。</li><li data-src-line="10" data-src-file="csharp/index.md"><strong><a href="./02-dotnet-runtime/chapter-01-compilation-clr.html">02 .NET 运行时</a></strong>：编译与 CLR、类型布局与内存、GC、JIT 与 AOT、非托管互操作。</li><li data-src-line="11" data-src-file="csharp/index.md"><strong><a href="./03-csharp-concurrency/chapter-01-why-async.html">03 C# 并发与异步</a></strong>：异步模型、Task 与 async/await、取消、线程与同步、并行与 LINQ、内存模型、lock 与 Monitor、无锁编程、并发集合、线程池、异步流与 Channels、常见并发缺陷。</li><li data-src-line="12" data-src-file="csharp/index.md"><strong><a href="./04-aspnet-core/chapter-01-why-aspnet-core.html">04 ASP.NET Core</a></strong>：Minimal API、路由与 MVC、中间件管道、依赖注入、配置与日志。</li><li data-src-line="13" data-src-file="csharp/index.md"><strong><a href="./05-network/chapter-01-http-client.html">05 网络</a></strong>：HttpClient 与 HttpClientFactory、Socket 与 TCP、gRPC、SignalR。</li><li data-src-line="14" data-src-file="csharp/index.md"><strong><a href="./06-data-access/chapter-01-persistence-thought.html">06 数据访问</a></strong>：持久化思想、EF Core、查询与调优、迁移、测试、ADO.NET、Dapper、事务与隔离级别、索引与执行计划。</li><li data-src-line="15" data-src-file="csharp/index.md"><strong><a href="./07-diagnostics/">07 诊断</a></strong>：内存、并发、CPU 性能的排查方法与生产案例。</li></ul><h2 id="学习路径" tabindex="-1" data-src-line="17" data-src-file="csharp/index.md">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><p data-src-line="19" data-src-file="csharp/index.md">适合按知识体系学习，从语言机制逐步深入：</p><ol data-src-line="21" data-src-file="csharp/index.md"><li data-src-line="21" data-src-file="csharp/index.md">完成 C# 语言：类型系统、对象与值语义、面向对象、泛型、委托、异常、集合与 LINQ，以及序列化、反射和现代语言特性。</li><li data-src-line="22" data-src-file="csharp/index.md">沿编译模型、类型布局、GC、JIT/AOT 理解程序如何运行。</li><li data-src-line="23" data-src-file="csharp/index.md">学习异步模型、Task、内存模型、锁与并发原语。</li><li data-src-line="24" data-src-file="csharp/index.md">根据工作方向进入 ASP.NET Core、网络或数据访问。</li><li data-src-line="25" data-src-file="csharp/index.md">最后通过诊断方法与生产案例串联前面的机制。</li></ol><h2 id="内容边界" tabindex="-1" data-src-line="27" data-src-file="csharp/index.md">内容边界 <a class="header-anchor" href="#内容边界" aria-label="Permalink to &quot;内容边界&quot;">​</a></h2><ul data-src-line="29" data-src-file="csharp/index.md"><li data-src-line="29" data-src-file="csharp/index.md">C# 专题负责语言机制、类型系统、.NET 运行时、并发异步与应用开发。</li><li data-src-line="30" data-src-file="csharp/index.md">设计模式、架构原则、可观测性等跨语言实践由 <a href="./../design-pattern/">设计模式</a> 与 <a href="./../engineering/">工程</a> 专题负责，本专题只解释它们在 C# 中的落地。</li><li data-src-line="31" data-src-file="csharp/index.md">Java 专题负责 JVM 生态的对应机制；两者内容并行，遇到相同概念时互相链接而非重复。</li></ul>',10)])])}const f=e(s,[["render",d]]);export{m as __pageData,f as default};
